import { MeshPhysicalNodeMaterial, Group, Mesh, PlaneGeometry, BoxGeometry, Color, PointLight } from 'three/webgpu';
import { texture, uv, vec2, vec3, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'loop-column-gallery';
  group.position.set(0, 0, 0);

  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE',
  ];

  const COUNT = 6;
  const PITCH = 1.5;
  const LOOP_LEN = 9.0;
  const COL_X = 0.9;
  const PLATE_W = 1.9;
  const PLATE_H = 1.2;
  const INK = new Color(0x16161d);
  const ACCENT = new Color(0xff2a38);

  const baseTex = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-mock/home/nodes/feature-card.png');

  const plateColumn = new Group();
  plateColumn.position.x = COL_X;
  group.add(plateColumn);

  const plates = [];
  const uvOffsets = [
    { off: vec2(0.0, 0.0), scl: vec2(1.0, 1.0) },
    { off: vec2(0.1, 0.05), scl: vec2(0.8, 0.8) },
    { off: vec2(0.2, 0.0), scl: vec2(0.7, 0.75) },
    { off: vec2(0.0, 0.15), scl: vec2(0.85, 0.7) },
    { off: vec2(0.15, 0.1), scl: vec2(0.75, 0.85) },
    { off: vec2(0.05, 0.2), scl: vec2(0.9, 0.65) },
  ];

  const disposables = [];

  for (let i = 0; i < COUNT; i++) {
    const plateGroup = new Group();
    const y0 = -i * PITCH;
    plateGroup.userData.baseY = y0;
    plateGroup.position.y = y0;

    const geo = new PlaneGeometry(PLATE_W, PLATE_H);
    const mat = new MeshPhysicalNodeMaterial();
    const { off, scl } = uvOffsets[i % uvOffsets.length];
    const suv = uv().mul(scl).add(off);
    mat.colorNode = texture(baseTex, suv).mul(color(0xffffff));
    mat.roughness = 0.6;
    mat.metalness = 0.1;
    mat.clearcoat = 0.1;
    const mesh = new Mesh(geo, mat);
    plateGroup.add(mesh);
    disposables.push(geo, mat);

    // machined bevel frame (thin border boxes)
    const bevelMat = new MeshPhysicalNodeMaterial();
    bevelMat.colorNode = color(INK);
    bevelMat.roughness = 0.5;
    bevelMat.metalness = 0.5;
    disposables.push(bevelMat);

    const bevelThickness = 0.03;
    const frameParts = [
      { w: PLATE_W + bevelThickness * 2, h: bevelThickness, x: 0, y: PLATE_H / 2 + bevelThickness / 2 },
      { w: PLATE_W + bevelThickness * 2, h: bevelThickness, x: 0, y: -PLATE_H / 2 - bevelThickness / 2 },
      { w: bevelThickness, h: PLATE_H + bevelThickness * 2, x: -PLATE_W / 2 - bevelThickness / 2, y: 0 },
      { w: bevelThickness, h: PLATE_H + bevelThickness * 2, x: PLATE_W / 2 + bevelThickness / 2, y: 0 },
    ];
    for (const p of frameParts) {
      const bg = new PlaneGeometry(p.w, p.h);
      const bm = new Mesh(bg, bevelMat);
      bm.position.set(p.x, p.y, -0.005);
      plateGroup.add(bm);
      disposables.push(bg);
    }

    // accent strip (hidden by default via emissive intensity 0)
    const accentGeo = new BoxGeometry(0.03, PLATE_H, 0.02);
    const accentMat = new MeshPhysicalNodeMaterial();
    accentMat.colorNode = color(ACCENT);
    accentMat.emissiveNode = color(ACCENT).mul(0.0);
    accentMat.roughness = 0.4;
    accentMat.metalness = 0.3;
    const accentMesh = new Mesh(accentGeo, accentMat);
    accentMesh.position.set(-PLATE_W / 2 - 0.02, 0, 0.01);
    plateGroup.add(accentMesh);
    disposables.push(accentGeo, accentMat);
    plateGroup.userData.accentMat = accentMat;

    // caption
    const captionText = ctx.fontAtlas.createText({
      text: captions[i % captions.length],
      font: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: '#e8ecf2',
    });
    captionText.position.set(-1.6 - COL_X, -PLATE_H / 2 + 0.15, 0.02);
    captionText.material && (captionText.material.transparent = true);
    if (captionText.material) captionText.material.opacity = 0;
    plateGroup.add(captionText);
    plateGroup.userData.captionText = captionText;

    plateColumn.add(plateGroup);
    plates.push(plateGroup);
  }

  // headline
  const headline = ctx.fontAtlas.createText({
    text: 'Inside the atelier',
    font: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(-1.6, 1.9, 0);
  group.add(headline);

  // accent light for focused plate
  const focusLight = new PointLight(0xff2a38, 1.4, 3);
  focusLight.position.set(-1.6, 0, 0.5);
  group.add(focusLight);

  // apply fly-through primitive
  if (ctx.primitives && ctx.primitives['fly-through']) {
    ctx.primitives['fly-through'](group, { depthUnits: 2.5, trigger: 'scroll' });
  }

  // scroll-driven weighted inertia
  const scrollState = { target: 0, current: 0, velocity: 0 };
  let focusedPlate = null;

  function updateFocus() {
    let closest = null;
    let closestDist = Infinity;
    for (const p of plates) {
      const worldY = ((p.userData.baseY - scrollState.current) % LOOP_LEN + LOOP_LEN) % LOOP_LEN;
      const wrapped = worldY > LOOP_LEN / 2 ? worldY - LOOP_LEN : worldY;
      p.position.y = wrapped;
      const dist = Math.abs(wrapped);
      if (dist < closestDist) {
        closestDist = dist;
        closest = p;
      }
    }
    if (closest !== focusedPlate) {
      if (focusedPlate) {
        gsap.to(focusedPlate.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out' });
        if (focusedPlate.userData.accentMat) {
          gsap.to(focusedPlate.userData.accentMat.emissiveNode, {}, 0);
          focusedPlate.userData.accentMat.emissiveNode = color(ACCENT).mul(0.0);
        }
        if (focusedPlate.userData.captionText?.material) {
          gsap.to(focusedPlate.userData.captionText.material, { opacity: 0, duration: 0.3 });
        }
      }
      focusedPlate = closest;
      if (focusedPlate) {
        gsap.fromTo(
          focusedPlate.scale,
          { x: 1, y: 1, z: 1 },
          { x: 1.06, y: 1.06, z: 1.06, duration: 0.35, ease: 'power2.out' }
        );
        if (focusedPlate.userData.accentMat) {
          focusedPlate.userData.accentMat.emissiveNode = color(ACCENT).mul(1.4);
        }
        if (focusedPlate.userData.captionText?.material) {
          gsap.fromTo(
            focusedPlate.userData.captionText.material,
            { opacity: 0 },
            { opacity: 1, duration: 0.4, ease: 'power2.out' }
          );
        }
      }
    }
  }

  function onScroll(delta) {
    scrollState.target += delta * PITCH;
  }

  function onFrame() {
    const diff = scrollState.target - scrollState.current;
    scrollState.velocity += diff * 0.12;
    scrollState.velocity *= 0.85;
    scrollState.current += scrollState.velocity * 0.12;
    updateFocus();
  }

  updateFocus();

  group.userData.handlers = {
    scroll: onScroll,
    frame: onFrame,
  };

  group.userData.cleanup = () => {
    gsap.killTweensOf(plates.map((p) => p.scale));
    plates.forEach((p) => {
      if (p.userData.captionText?.material) gsap.killTweensOf(p.userData.captionText.material);
    });
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    baseTex && baseTex.dispose && baseTex.dispose();
  };

  return group;
}
